SYSTEMS=["graph_rag"]
def run_experiment(cases,split,generate):
    answers=[]
    for case in cases:
        for system in SYSTEMS: answers.append({"id":case["id"],"system":system,"answer":generate(case,system)})
    return {"manifest":{"split":split},"answers":answers}

def score_answers(cases,answers,judge,apply_overrides=False):
    rows=[]
    for answer in answers:
        case=next(c for c in cases if c["id"]==answer["id"]); score=judge(case,answer)
        if apply_overrides and case.get("legacy_override"): score.update(case["legacy_override"])
        rows.append({**answer,**score,"adjudication":"scored"})
    return rows

import unittest
from runner import run_experiment
class PublicTest(unittest.TestCase):
    def test_manifest_split(self): self.assertEqual("dev",run_experiment([],"dev",lambda c,s:"")["manifest"]["split"])
if __name__=="__main__": unittest.main()
